wwv_flow_imp_page.create_page(
 p_id=>100
,p_name=>'Login Page'
,p_alias=>'LOGIN-PAGE'
,p_step_title=>'Login Page'
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(16136146539209132)
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Maak de volledige pagina een flexbox met een subtiele achtergrond */',
'.t-PageBody--login {',
'    background: linear-gradient(to right, #004bad, #0080ff); /* Blauwe gradient */',
'    background-attachment: fixed;',
'    display: flex;',
'    justify-content: space-between; /* Zorgt voor evenwichtige verdeling */',
'    align-items: center;',
'    height: 100vh;',
'    padding: 0 10%;',
'    gap: 50px; /* Ruimte tussen left en right */',
'}',
'',
'/* Stijl de Oracle APEX container correct */',
'.container {',
'    display: flex;',
'    justify-content: space-between;',
'    width: 100%;',
'}',
'',
'',
'/* Linkerzijde (Welkom sectie) */',
'.left {',
'    flex: 1;',
'    max-width: 50%; /* Laat left iets meer ruimte gebruiken */',
'    display: flex;',
'    flex-direction: column;',
'    align-items: flex-start;',
'    text-align: left;',
'    color: white;',
'    position: relative; /* Zorgt ervoor dat margin correct werkt */',
'    margin-top: -30px; /* Klein beetje omhoog */',
'}',
'',
'/* Afbeelding boven de tekst */',
'.left img {',
'    max-width: 400px; /* Nog iets groter voor betere focus */',
'    height: auto;',
'    border-radius: 15px;',
'    margin-bottom: 40px;',
'    box-shadow: 0px 10px 25px rgba(0, 0, 0, 0.3);',
'}',
'',
'/* Zorg ervoor dat de tekst niet afbreekt */',
'.left h1 {',
'    font-size: 52px; /* Grootte blijft opvallend */',
'    font-weight: 800; /* Extra vet voor meer impact */',
'    margin-bottom: 15px;',
'    text-align: left;',
'    width: auto; /* Zorgt dat de breedte zich aanpast */',
'    max-width: fit-content; /* Past zich alleen aan de tekstbreedte aan */',
'    white-space: nowrap; /* Voorkomt dat het breekt naar een tweede regel */',
'    overflow: hidden;',
'    text-overflow: ellipsis; /* Mocht er te weinig ruimte zijn, toon een "..." */',
'}',
'',
'/* Ondertekst verbeteren */',
'.left p {',
'    font-size: 22px; /* Iets groter voor betere balans */',
'    opacity: 1; /* Maak het iets helderder */',
'    max-width: 100%; /* Gebruik de volledige breedte */',
'    text-align: left;',
'    line-height: 1.5; /* Zorgt voor prettige leesbaarheid */',
'}',
'',
'/* Rechterzijde (Login-box) */',
'#right {',
'    flex: 1;',
'    max-width: 35%;',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'}',
'',
'#P100_PASSWORD_error {',
'    color: #d32f2f; /* Donkerrood voor duidelijke foutmelding */',
'    background-color: #fdecea; /* Lichte rode achtergrond */',
'    border-left: 4px solid #d32f2f; /* Rode zijbalk voor extra accent */',
'    padding: 10px;',
'    border-radius: 5px;',
'    font-size: 14px;',
'    font-weight: bold;',
'    display: inline-block;',
'    margin-top: 5px;',
'    animation: fadeIn 0.3s ease-in-out;',
'    width: 100%;',
'}',
'',
'#P100_USERNAME_error {',
'    color: #d32f2f; /* Donkerrood voor duidelijke foutmelding */',
'    background-color: #fdecea; /* Lichte rode achtergrond */',
'    border-left: 4px solid #d32f2f; /* Rode zijbalk voor extra accent */',
'    padding: 10px;',
'    border-radius: 5px;',
'    font-size: 14px;',
'    font-weight: bold;',
'    display: inline-block;',
'    margin-top: 5px;',
'    animation: fadeIn 0.3s ease-in-out;',
'    width: 100%;',
'',
'}',
'',
'#P100_REMEMBER_error {',
'    color: #d32f2f; /* Donkerrood voor duidelijke foutmelding */',
'    background-color: #fdecea; /* Lichte rode achtergrond */',
'    border-left: 4px solid #d32f2f; /* Rode zijbalk voor extra accent */',
