wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(16320151460072208)
,p_chart_id=>wwv_flow_imp.id(16320033707072207)
,p_seq=>10
,p_name=>'Donut'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH total_errors AS (',
'  SELECT SUM(er.error_count) AS total',
'  FROM   icca_fom_errors er',
'  JOIN   icca_adt_forms fom ON fom.id = er.fom_id',
'  WHERE  fom.adt_id = :P2000_ADT_ID',
'),',
'error_sums AS (',
'  SELECT',
'    SUM(CASE ',
'        WHEN LOWER(ete.name) IN (''niet gehecht vuil licht stof'', ''niet gehecht vuil methode'') ',
'        THEN er.error_count ELSE 0 ',
'    END) AS groen_count,',
'',
'    SUM(CASE ',
'        WHEN LOWER(ete.name) IN (''aanslag'', ''gehecht vuil vlek vingertast'', ''dicht stof'', ''gehecht vuil methode'') ',
'        THEN er.error_count ELSE 0 ',
'    END) AS blauw_count,',
'',
'    SUM(CASE ',
'        WHEN LOWER(ete.name) IN (''niet aangevuld'', ''niet geleegd'', ''spinrag'') ',
'        THEN er.error_count ELSE 0 ',
'    END) AS bruin_count',
'  FROM  icca_fom_errors er',
'  JOIN  icca_adt_forms fom ON fom.id = er.fom_id',
'  JOIN  icca_error_types ete ON ete.id = er.ete_id',
'  WHERE fom.adt_id = :P2000_ADT_ID',
')',
'SELECT ''groen'' AS label,',
'       ROUND(groen_count * 100 / total.total, 1) AS value',
'FROM error_sums, total_errors total',
'UNION ALL',
'SELECT ''blauw'' AS label,',
'       ROUND(blauw_count * 100 / total.total, 1) AS value',
'FROM error_sums, total_errors total',
'UNION ALL',
'SELECT ''bruin'' AS label,',
'       ROUND(bruin_count * 100 / total.total, 1) AS value',
'FROM error_sums, total_errors total;',
''))
,p_ajax_items_to_submit=>'P2000_ADT_ID'
,p_items_value_column_name=>'VALUE'
,p_items_label_column_name=>'LABEL'
,p_items_label_rendered=>false
);
