,p_name=>'New'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'  day_number,',
'  ''Cijfer'' AS series_name,',
'  cijfer_value AS value,',
'  ''27-dec'' AS y_axis_date',
'FROM (',
'  SELECT 1 AS day_number, 6.2 AS cijfer_value FROM dual UNION ALL',
'  SELECT 2, 7.4 FROM dual UNION ALL',
'  SELECT 3, 5.8 FROM dual UNION ALL',
'  SELECT 4, 6.0 FROM dual UNION ALL',
'  SELECT 5, 8.2 FROM dual UNION ALL',
'  SELECT 6, 5.6 FROM dual UNION ALL',
'  SELECT 7, 7.3 FROM dual UNION ALL',
'  SELECT 8, 6.9 FROM dual UNION ALL',
'  SELECT 9, 7.6 FROM dual UNION ALL',
'  SELECT 10, 8.4 FROM dual',
')',
'',
'UNION ALL',
'',
'SELECT',
'  day_number,',
'  ''2 per zw gem'' AS series_name,',
'  zw_value AS value,',
'  ''27-dec'' AS y_axis_date',
'FROM (',
'  SELECT 1 AS day_number, 4.2 AS zw_value FROM dual UNION ALL',
'  SELECT 2, 5.0 FROM dual UNION ALL',
'  SELECT 3, 6.5 FROM dual UNION ALL',
'  SELECT 4, 5.2 FROM dual UNION ALL',
'  SELECT 5, 7.1 FROM dual UNION ALL',
'  SELECT 6, 4.8 FROM dual UNION ALL',
'  SELECT 7, 5.6 FROM dual UNION ALL',
'  SELECT 8, 6.0 FROM dual UNION ALL',
'  SELECT 9, 7.2 FROM dual UNION ALL',
'  SELECT 10, 6.8 FROM dual',
')',
''))
