,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob BLOB;',
'    l_clob CLOB;',
'    l_json VARCHAR2(4000);',
'BEGIN',
'    -- Retrieve Base64 CLOB from APEX session variable',
'    l_clob := apex_application.g_clob_01;',
'',
'    -- Check if the CLOB is empty (to avoid errors)',
'    IF l_clob IS NULL THEN',
'        htp.p(''{"status": "error", "message": "Base64 data is missing"}'');',
'        RETURN;',
'    END IF;',
'',
'    -- Convert Base64 CLOB to BLOB',
'    l_blob := apex_web_service.clobbase642blob(l_clob);',
'',
'    -- Store BLOB in database',
'    INSERT INTO icca_charts_images (image, adt_id) VALUES (l_blob, apex_application.g_x01);',
'    COMMIT;',
'',
'    -- Return JSON response',
'    l_json := ''{"status": "success", "message": "Image stored successfully"}'';',
'    htp.p(l_json);',
'EXCEPTION WHEN OTHERS THEN',
'    -- Capture SQL error and return a JSON message instead of plain text',
'    l_json := ''{"status": "error", "message": "'' || SQLERRM || ''"}'';',
'    htp.p(l_json);',
'END;',
''))
