'declare',
'  v_email    varchar2(100);',
'  v_counter  integer := 1;',
'begin',
'    loop',
'        v_email := trim(regexp_substr(:P8006_EMAIL, ''[^,]+'', 1, v_counter));',
'        exit when v_email is null;',
