,p_process_name=>'Set user password'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    cursor c_get_usr_password',
'    is',
'        select  password',
'        from    icca_users usr',
'        where   id = :P8006_USR_FORM_ID',
'        ;',
'    --',
'    lv_usr_password icca_users.password%type;',
'    --        ',
'begin',
'    --',
'    open    c_get_usr_password;',
'    fetch   c_get_usr_password',
'    into    lv_usr_password;',
'    close   c_get_usr_password;',
'    --',
'    if (    lv_usr_password is not null',
'        and :P8006_PASSWORD is null',
'    )',
'    then',
'        :P8006_PASSWORD := lv_usr_password;',
'    else',
'        :P8006_PASSWORD := icca_authentication.f_get_hash( pi_password => :P8006_PASSWORD );',
'    end if;',
'    --',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>9328024802252748
);
