);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(20428403216954764707)
,p_plug_name=>'Performers Report'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  pfr.id',
',       pfr.usr_id',
',       usr.username',
',       usr.active',
',       (   select  listagg(eml.email, ''<br>'') within group (order by eml.email)',
'            from    icca_usr_emails eml',
'            where   eml.usr_id = pfr.usr_id',
'            group by eml.usr_id',
'        ) email',
',       pfr.first_name',
',       pfr.last_name',
',       pfr.phone_number',
',       pfr.mobile_number',
',       pfr.is_auditor',
',       pfr.is_project_leader',
',       (select count(1) from icca_pfr_clients where pfr_id = pfr.id) aantal_klanten',
',       pfr.created_date',
',       pfr.created_by',
',       pfr.modified_date',
',       pfr.modified_by',
'from    icca_performers pfr',
