wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(20428705522056738636)
,p_validation_name=>'Validate Email Format'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  v_email    varchar2(100);',
'  v_counter  integer := 1;',
'begin',
'    loop',
'        v_email := trim(regexp_substr(:P8008_EMAIL, ''[^,]+'', 1, v_counter));',
'        exit when v_email is null;',
'',
'        -- Controleer het e-mailformaat met een eenvoudige regex (kan complexer indien nodig)',
'        if not regexp_like(v_email,',
'            ''^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$'')',
'        then',
'            return false;',
'        end if;',
'',
'        v_counter := v_counter + 1;',
'    end loop;',
'',
'    return true;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Ongeldig e-mailadres. Gebruik het formaat: naam@domein.com.'
,p_validation_condition=>'CREATE,SAVE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
,p_associated_item=>wwv_flow_imp.id(20427722994239239582)
,p_error_display_location=>'INLINE_WITH_FIELD'
);
