,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign Clients to performers'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    --',
'    delete from icca_pfr_clients where pfr_id = :P8008_ID;',
'    --',
'    for cnt in  (   select  trim(regexp_substr(:P8008_CLIENTS, ''[^:]+'', 1, level)) id',
'                    from    dual',
'                    connect by level <= regexp_count(:P8008_CLIENTS, '':'')+1',
'    )',
'    loop',
'        insert into icca_pfr_clients (pfr_id, cnt_id)',
'            values (:P8008_ID, cnt.id)',
'            ;',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'Performer gegevens succesvol verwerkt.'
,p_internal_uid=>5934329579240641
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(17970716525466339)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process User emails'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_email  varchar2(100);',
'begin',
'    -- 1. Insert / update (merge)',
'    for v in (  select trim(regexp_substr(:P8008_EMAIL, ''[^,]+'', 1, level)) as email',
'                from dual',
'                connect by regexp_substr(:P8008_EMAIL, ''[^,]+'', 1, level) is not null',
'            )',
'    loop',
'        v_email := v.email;',
'',
'        merge into icca_usr_emails tgt',
'            using (select :P8008_ID_1 as usr_id, v_email as email from dual) src',
'            on (tgt.usr_id = src.usr_id and tgt.email = src.email)',
'        when matched then',
'          update set modified_date = sysdate, modified_by = :APP_USER',
'        when not matched then',
'          insert (usr_id, email, created_date, created_by)',
'          values (src.usr_id, src.email, sysdate, :APP_USER);',
'    end loop;',
'',
'    -- 2. Delete e-mails die niet meer in :P8008_EMAIL voorkomen',
'    delete from icca_usr_emails',
'    where usr_id = :P8008_ID_1',
'    and email not in (',
'      select trim(regexp_substr(:P8008_EMAIL, ''[^,]+'', 1, level))',
'      from dual',
'      connect by regexp_substr(:P8008_EMAIL, ''[^,]+'', 1, level) is not null',
'    );',
'',
'    commit;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>17970716525466339
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(20432390460611124633)
