,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  cat.id',
',       cat.name',
',       cat.fixed_value',
',       count(1) aantal_klanten',
',       cat.active',
',       cat.created_date',
',       cat.created_by',
',       cat.modified_date',
',       cat.modified_by',
'from    icca_categories     cat',
'left join icca_cat_clients  clt on cat.id = clt.cat_id',
'group by    cat.id',
'        ,   cat.name',
'        ,   cat.fixed_value',
'        ,   cat.active',
'        ,   cat.created_date',
'        ,   cat.created_by',
'        ,   cat.modified_date',
'        ,   cat.modified_by',
'order by cat.created_by desc        '))
