wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(20428592836147979787)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign Clients to categories'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    --',
'    delete from icca_cat_clients where cat_id = :P8018_ID;',
'    --',
'    for cnt in  (   select  trim(regexp_substr(:P8018_CLIENTS, ''[^:]+'', 1, level)) id',
'                    from    dual',
'                    connect by level <= regexp_count(:P8018_CLIENTS, '':'')+1',
'    )',
'    loop',
'        insert into icca_cat_clients (cat_id, cnt_id)',
'            values (:P8018_ID, cnt.id)',
'            ;',
'    end loop;',
'    --',
'    update  icca_categories',
'    set     name = :P8018_NAME',
'    where   id = :P8018_ID',
'    ;',
'    --',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
