wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(20429969174879189962)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process Category limits'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    merge into icca_cat_limits dest',
'        using ( select  :P8018_ID                   cat_id',
'                ,       :P8018_CBE_MIN_0            cbe_id',
'                ,       :P8018_MIN_SIZE_RANGE_0     min_size_range',
'                ,       :P8018_MAX_SIZE_RANGE_0     max_size_range',
'                ,       :P8018_APPROVE_LIMIT_0      approve_limit',
'                from    dual',
'                union all',
'                select  :P8018_ID                   cat_id',
'                ,       :P8018_CBE_MIN_250          cbe_id',
'                ,       :P8018_MIN_SIZE_RANGE_250   min_size_range',
'                ,       :P8018_MAX_SIZE_RANGE_250   max_size_range',
'                ,       :P8018_APPROVE_LIMIT_250    approve_limit',
'                from    dual',
'                union all',
'                select  :P8018_ID                   cat_id',
'                ,       :P8018_CBE_MIN_500          cbe_id',
'                ,       :P8018_MIN_SIZE_RANGE_500   min_size_range',
'                ,       :P8018_MAX_SIZE_RANGE_500   max_size_range',
'                ,       :P8018_APPROVE_LIMIT_500    approve_limit',
'                from    dual',
'        ) src',
'    on (    dest.cat_id = src.cat_id',
'        and dest.cbe_id = src.cbe_id',
'        )',
'    when not matched then',
'        insert (dest.cat_id, dest.cbe_id, dest.min_size_range, dest.max_size_range, dest.approve_limit)',
'            values(src.cat_id, src.cbe_id, src.min_size_range, src.max_size_range, src.approve_limit)',
'    when matched then',
'        update set  dest.min_size_range = src.min_size_range             ',
'                ,   dest.max_size_range = src.max_size_range             ',
'                ,   dest.approve_limit  = src.approve_limit              ',
'    ;',
'    update  icca_categories',
'    set     name = :P8018_NAME',
'    where   id = :P8018_ID',
'    ;    ',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'Categorie gegevens succesvol verwerkt.'
,p_internal_uid=>7397308207330818
);
