,p_process_type=>'NATIVE_FORM_DML'
,p_process_name=>'Process form Onderhoud: KPI Elementen Form'
,p_attribute_01=>'REGION_SOURCE'
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_attribute_08=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'KPI Element gegevens succesvol verwerkt.'
,p_internal_uid=>8560924138560153
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(20431050006570054866)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign Clients to KPI Elements'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    --',
'    -- delete from icca_ket_clients where ket_id = :P8024_ID;',
'    --',
'    for kcn in  (   select  trim(regexp_substr(:P8024_CLIENTS, ''[^:]+'', 1, level)) id',
'                    from    dual',
'                    connect by level <= regexp_count(:P8024_CLIENTS, '':'')+1',
'    )',
'    loop',
'        -- insert into icca_ket_clients (ket_id, cnt_id)',
'        --     values (:P8024_ID, kcn.id)',
'        --     ;',
'        merge into icca_ket_clients dest',
'            using ( select  :P8024_ID   ket_id',
'                    ,       kcn.id      cnt_id       ',
'                    from    dual',
'                ) src',
'            on (    src.ket_id = dest.ket_id ',
'                and src.cnt_id = dest.cnt_id ',
'                )',
'        when not matched ',
'            then insert (ket_id, cnt_id)',
'                values (:P8024_ID, kcn.id)',
'            ;',
'    end loop;',
'    --',
'    update  icca_kpi_elementen',
'    set     name = :P8024_NAME',
'    where   id = :P8024_ID',
'    ;',
'    --',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'KPI Element gegevens succesvol verwerkt.'
,p_internal_uid=>8478139898195722
);
